"""The commons research story and its resource-page introduction."""
from html import escape

# Paragraphs are kept together here so that the three languages cover the same facts.
STORY = [
('title', 'Quem cuida dos espaços que os vizinhos dividem?', 'Who looks after the places neighbours share?', 'Wie zorgt voor de plekken die buren delen?'),
('heading', 'Uma casa e um lugar compartilhado', 'A home and a place held in common', 'Een huis en een gedeelde plek'),
('p', 'Imagine um bairro de casas ao redor de uma área verde. Cada família tem sua casa, e todas compartilham uma cisterna, painéis solares, caminhos e um pomar. As crianças brincam sob árvores plantadas quando as primeiras famílias chegaram.', 'Imagine a neighbourhood of houses around a green. The families have their own homes, and they share a cistern, solar panels, paths and an orchard. Children play under trees that were planted when the first families arrived.', 'Stel je een buurt voor met huizen rond een groen plein. Elk gezin heeft een eigen huis en samen delen ze een waterreservoir, zonnepanelen, paden en een boomgaard. Kinderen spelen onder bomen die de eerste bewoners plantten.'),
('p', 'Anos depois, uma família vende sua casa. Uma bomba quebra. Alguns vizinhos discordam sobre o pagamento do conserto. Uma pessoa fez quase todo o trabalho de organização e está exausta. Quem decide o que acontece? Como manter a área verde e a água disponíveis para as próximas famílias?', 'Years later, a family sells its house. A pump breaks. Some neighbours disagree about paying for repairs. One person has done most of the organising and is exhausted. Who decides what happens next? What keeps the green and the water available to the next families?', 'Jaren later verkoopt een gezin zijn huis. Een pomp gaat stuk. Buren zijn het oneens over wie de reparatie betaalt. Eén persoon deed het meeste regelwerk en is uitgeput. Wie beslist wat er gebeurt? Hoe blijven het groen en het water beschikbaar voor de volgende gezinnen?'),
('p', 'Essas perguntas orientam nossa pesquisa sobre cooperativas de moradia, comunidades intencionais e ecovilas. Estudamos suas conquistas e dificuldades para entender o que é necessário para cuidar de algo em conjunto ao longo do tempo.', 'These questions sit behind our research into housing cooperatives, intentional communities and ecovillages. We looked at their achievements and the difficulties they faced, to understand what it takes to care for something together over time.', 'Deze vragen staan centraal in ons onderzoek naar wooncoöperaties, leefgemeenschappen en ecodorpen. We keken naar hun successen en moeilijkheden om te begrijpen wat nodig is om samen langdurig voor iets te zorgen.'),
('heading', 'Por que o que é compartilhado pode se perder', 'Why shared things can be lost', 'Waarom gedeelde voorzieningen verloren kunnen gaan'),
('p', 'Em 1968, o biólogo Garrett Hardin descreveu a “tragédia dos comuns”: pessoas usando um recurso compartilhado em benefício próprio poderiam acabar esgotando esse recurso. Seu exemplo imaginava uma pastagem aberta a criadores de gado, cada um acrescentando mais animais.', 'In 1968, biologist Garrett Hardin described the “tragedy of the commons”: people using a shared resource for their own benefit could eventually exhaust it. His example imagined a pasture open to herders, each adding more animals.', 'In 1968 beschreef bioloog Garrett Hardin de “tragedie van de meent”: mensen die een gedeelde hulpbron voor eigen voordeel gebruiken, kunnen die uiteindelijk uitputten. Zijn voorbeeld was een open weide waarop veehouders steeds meer dieren laten grazen.'),
('p', 'A cientista política e economista Elinor Ostrom estudou comunidades que encontraram outro caminho. Pessoas que usavam florestas, áreas de pesca e sistemas de irrigação às vezes combinavam quem poderia usá-los, quanto cada pessoa poderia retirar, quem acompanharia as regras e como resolver disputas. Ela encontrou diversos acordos locais, em vez de uma regra que servisse para todos os lugares.', 'Political economist Elinor Ostrom studied communities that had found another path. People using forests, fisheries and irrigation systems sometimes agreed who could use them, how much each person could take, who would monitor the rules and how disputes would be resolved. She found many local arrangements, rather than one rule that worked everywhere.', 'Politiek econoom Elinor Ostrom onderzocht gemeenschappen die een andere weg vonden. Gebruikers van bossen, visgronden en irrigatiesystemen maakten soms afspraken over toegang, gebruik, toezicht en het oplossen van conflicten. Ze vond uiteenlopende plaatselijke afspraken, geen regel die overal werkte.'),
('p', 'A distinção importa para a moradia. Um pátio compartilhado tem mais chances de ser cuidado quando as pessoas que o usam sabem o que podem fazer ali, quem paga pela manutenção e como as decisões são tomadas. Esses acordos precisam se ajustar às pessoas e ao lugar.', 'The distinction matters for housing. A shared courtyard is more likely to be cared for when the people who use it know what they can do there, who pays for maintenance and how decisions are made. Those arrangements still need to fit the people and the place.', 'Dat onderscheid is ook bij wonen van belang. Een gedeelde binnenplaats krijgt eerder de nodige zorg als bewoners weten hoe zij die mogen gebruiken, wie het onderhoud betaalt en hoe besluiten worden genomen. Die afspraken moeten passen bij de mensen en de plek.'),
('links', [('Artigo de Hardin de 1968', 'Hardin’s 1968 article', 'Hardins artikel uit 1968', 'https://www.law.berkeley.edu/archive/files/CLEE/Hardin_1968_Science_TragedyOfTheCommons.pdf'), ('Conferência de Ostrom no Nobel', 'Ostrom’s Nobel lecture', 'Ostroms Nobellezing', 'https://www.nobelprize.org/prizes/economic-sciences/2009/ostrom/lecture/')]),
('heading', 'Quando famílias defenderam suas moradias coletivas', 'When families defended their shared homes', 'Toen gezinnen hun gezamenlijke woningen verdedigden'),
('p', 'No Uruguai, famílias construíram moradias juntas por meio de cooperativas de ajuda mútua. A FUCVAM, sua federação, foi fundada em 1970. Suas cooperativas se baseiam na propriedade coletiva, e os membros se organizam e ajudam a construir as moradias. O acesso à terra e ao financiamento exigiu anos de negociação.', 'In Uruguay, families built homes together through mutual-aid housing cooperatives. FUCVAM, their federation, was founded in 1970. Its cooperatives are based on collective ownership, and members organise and help build their homes. Access to land and financing took years of negotiation.', 'In Uruguay bouwden gezinnen samen huizen via wooncoöperaties op basis van wederzijdse hulp. Hun federatie FUCVAM werd opgericht in 1970. De coöperaties gaan uit van gezamenlijk eigendom; leden organiseren zich en helpen met de bouw. Toegang tot grond en financiering kostte jaren van onderhandelen.'),
('p', 'Durante a ditadura uruguaia, o governo tentou mudar o modelo de propriedade coletiva. A FUCVAM e seus aliados recolheram assinaturas para um referendo contra a mudança. Segundo a instituição nacional de direitos humanos do Uruguai, o governo ignorou as assinaturas e continuou aplicando a lei. Um relatório da comissão de memória da mesma instituição afirma que a mobilização ajudou a reverter a mudança. A sede da federação é reconhecida como um lugar de resistência à ditadura.', 'During Uruguay’s dictatorship, the government tried to change the collective ownership model. FUCVAM and its allies gathered signatures for a referendum to challenge the change. Uruguay’s human-rights institution says the government ignored the signatures and continued to apply the law. A report from its memory commission says the mobilisation helped reverse the change. The federation’s headquarters is recognised as a place of resistance to the dictatorship.', 'Tijdens de Uruguayaanse dictatuur probeerde de regering het model van collectief eigendom te veranderen. FUCVAM en bondgenoten verzamelden handtekeningen voor een referendum tegen de verandering. Volgens de nationale mensenrechteninstelling negeerde de regering de handtekeningen en bleef zij de wet toepassen. Een rapport van de herinneringscommissie van die instelling stelt dat de mobilisatie hielp om de verandering terug te draaien. Het hoofdkwartier van FUCVAM is erkend als plek van verzet tegen de dictatuur.'),
('p', 'Para a IMOBX, há uma diferença importante: as cooperativas da FUCVAM são proprietárias coletivas. O plano da IMOBX é que cada família se torne dona de sua casa. Os terrenos e serviços compartilhados ainda precisarão de proteção quando a propriedade das casas mudar. A forma dessa proteção no Brasil depende de orientação jurídica.', 'The lesson for IMOBX begins with a difference: FUCVAM’s cooperatives hold property collectively. IMOBX’s plan is for each family eventually to own its house. The shared land and services would still need protection when ownership of the houses changes. What form that protection can take in Brazil remains a question for legal advice.', 'Voor IMOBX is er een belangrijk verschil: de coöperaties van FUCVAM zijn gezamenlijk eigenaar. Bij IMOBX is het plan dat elk gezin uiteindelijk eigenaar wordt van zijn huis. De gedeelde grond en voorzieningen moeten beschermd blijven als huizen van eigenaar veranderen. Welke vorm daarvoor in Brazilië mogelijk is, vraagt juridisch advies.'),
('links', [('História da FUCVAM', 'FUCVAM’s history', 'Geschiedenis van FUCVAM', 'https://www.fucvam.org.uy/quienes-somos/historia/'), ('Instituição de direitos humanos do Uruguai sobre a resistência da FUCVAM', 'Uruguay’s human-rights institution on FUCVAM’s resistance', 'Uruguayaanse mensenrechteninstelling over het verzet van FUCVAM', 'https://www.gub.uy/institucion-nacional-derechos-humanos-uruguay/comision-nacional-honoraria-sitios-memoria/senalizaciones-memoria/sede-federacion-uruguaya'), ('Relatório da comissão de memória, página 50', 'Memory commission report, page 50', 'Rapport van de herinneringscommissie, pagina 50', 'https://www.gub.uy/institucion-nacional-derechos-humanos-uruguay/sites/institucion-nacional-derechos-humanos-uruguay/files/documentos/noticias/Primera%20Memoria%20anual%20.pdf#page=50')]),
('heading', 'Quem pode vender o que é compartilhado?', 'Who can sell what is shared?', 'Wie mag verkopen wat gedeeld wordt?'),
('p', 'O Mietshäuser Syndikat, na Alemanha, oferece uma resposta. Moradores se organizam e administram suas casas de aluguel. A rede tem poder de veto sobre a revenda de uma casa ou imóvel; assim, a associação de moradores não pode decidir pela venda sozinha. Os projetos também contribuem para um fundo de solidariedade que apoia outros projetos.', 'Germany’s Mietshäuser Syndikat offers one answer. Residents organise and run their rental houses. The network has a veto over resale of a house or property, so a decision to sell cannot be taken by the residents’ association alone. Projects also contribute to a solidarity fund that supports other projects.', 'Het Duitse Mietshäuser Syndikat biedt één antwoord. Bewoners organiseren en beheren hun huurhuizen. Het netwerk heeft vetorecht bij verkoop van een huis of pand, zodat de bewonersvereniging daar niet alleen over kan beslissen. Projecten dragen ook bij aan een solidariteitsfonds dat andere projecten steunt.'),
('p', 'Há uma troca: a proteção dá à rede mais ampla voz numa decisão que afeta os moradores. Essa estrutura protege casas de aluguel inteiras; ela não pode simplesmente ser copiada para um bairro onde cada família deve ser dona da própria casa.', 'There is a trade-off: the protection gives the wider network a say over a decision that affects the people living in the house. Its structure protects rental houses as a whole; it cannot simply be copied into a neighbourhood where families are meant to own individual homes.', 'Die bescherming brengt een afweging mee: het bredere netwerk krijgt zeggenschap over een besluit dat de bewoners raakt. De structuur beschermt huurhuizen als geheel en kan niet zomaar worden overgenomen in een buurt waar gezinnen een eigen huis bezitten.'),
('p', 'O Syndikat também descreve os riscos financeiros. No Eilhardshof, os custos de construção saíram do controle do grupo, e o projeto pediu falência em 2010. Uma proteção contra a revenda não paga os custos da obra.', 'The Syndikat also describes the financial risks. At Eilhardshof, construction costs escaped the group’s control and the project filed for bankruptcy in 2010. A safeguard against resale does not pay the building bills.', 'Het Syndikat beschrijft ook de financiële risico’s. Bij Eilhardshof kreeg de groep de bouwkosten niet meer onder controle en vroeg het project in 2010 faillissement aan. Bescherming tegen verkoop betaalt de bouwkosten niet.'),
('links', [('Como funciona o Syndikat e o que aconteceu em Eilhardshof', 'How the Syndikat operates and what happened at Eilhardshof', 'Hoe het Syndikat werkt en wat bij Eilhardshof gebeurde', 'https://www.syndikat.org/en/the-syndikat-in-operation/'), ('Como a rede está organizada', 'How its network is structured', 'Hoe het netwerk is opgebouwd', 'https://www.syndikat.org/en/the-building-blocks-of-the-network/')]),
('heading', 'Quando chegar a um acordo é difícil', 'When agreement becomes difficult', 'Wanneer overeenstemming moeilijk wordt'),
('p', 'Pessoas que compartilham uma visão ainda podem discordar sobre dinheiro, trabalho e a vida em comum. Um processo de decisão precisa dar voz às pessoas e permitir que a comunidade aja.', 'People who share a vision can still disagree about money, work and how to live together. A decision process needs to give people a voice while allowing the community to act.', 'Mensen met een gedeelde visie kunnen het nog steeds oneens zijn over geld, werk en het samenleven. Een besluitproces moet mensen een stem geven en de gemeenschap ook in staat stellen te handelen.'),
('p', 'Na ecovila Earthaven, na Carolina do Norte, os membros usaram por 18 anos um processo de consenso que exigia o acordo de todos que não se abstivessem. O relato de um membro, de 2013, descreve como o poder de uma só pessoa de bloquear uma decisão se tornou motivo de preocupação. Em 2012, a comunidade decidiu mudar o processo, mantendo aquele tipo de consenso para a admissão de membros.', 'At Earthaven Ecovillage in North Carolina, members used a consensus process for 18 years that required agreement from everyone who did not stand aside. A member’s 2013 account describes how the power of one person to block a decision became a source of concern. In 2012, the community agreed to change its process while retaining that form of consensus for admitting members.', 'In ecodorp Earthaven in North Carolina gebruikten leden achttien jaar lang een consensusproces waarbij iedereen die zich niet onthield moest instemmen. Een lid beschreef in 2013 hoe de mogelijkheid voor één persoon om een besluit te blokkeren zorgen veroorzaakte. In 2012 veranderde de gemeenschap het proces; voor het toelaten van leden bleef die vorm van consensus bestaan.'),
('p', 'Essa é a experiência de uma comunidade naquele período. Ela traz uma pergunta prática para a IMOBX: quais decisões devem ter o acordo de todas as famílias afetadas e quais os membros podem tomar juntos por votação?', 'This is one community’s experience at that time, not a rule every group must follow. It raises a practical question for IMOBX: which decisions should all affected families agree to, and which can members make together by a vote?', 'Dit is de ervaring van één gemeenschap in die periode. Ze roept een praktische vraag op voor IMOBX: met welke besluiten moeten alle betrokken gezinnen instemmen en welke kunnen leden samen bij stemming nemen?'),
('links', [('Relato sobre Earthaven', 'Read the Earthaven account', 'Lees het verhaal van Earthaven', 'https://ecovillage.org/resources-library/article/why-earthaven-ecovillage-usa-changed-its-decision-making-method/')]),
('heading', 'Preparação para anos difíceis', 'Planning for difficult years', 'Voorbereiden op moeilijke jaren'),
('p', 'Mesmo uma organização consolidada pode enfrentar várias crises ao mesmo tempo. Segundo o Findhorn Foundation Trust, os efeitos da COVID, incêndios que destruíram dois edifícios comunitários e o impacto do Brexit sobre os estudantes levaram seus administradores a decidir, em 2023, encerrar o trust. Eles decidiram transferir muitos bens para organizações comunitárias e a missão educacional para outra organização. A transição do trust é uma parte da história mais ampla de Findhorn, não o fim de toda a comunidade.', 'Even a long-established organisation can face several shocks at once. The Findhorn Foundation Trust says the effects of COVID, fires that destroyed two community buildings, and Brexit’s effect on students led its trustees to decide in 2023 to wind down the trust. The trustees decided to pass many assets to community organisations and transfer the education mission to another organisation. The trust’s transition is one part of the wider Findhorn story, not the end of the whole community.', 'Ook een organisatie met een lange geschiedenis kan meerdere tegenslagen tegelijk treffen. Volgens de Findhorn Foundation Trust leidden de gevolgen van COVID, branden die twee gemeenschapsgebouwen verwoestten en de invloed van Brexit op studenten ertoe dat het bestuur in 2023 besloot de trust af te wikkelen. Het bestuur besloot veel bezittingen aan gemeenschapsorganisaties over te dragen en de onderwijsmissie bij een andere organisatie onder te brengen. De overgang van de trust is één deel van het bredere verhaal van Findhorn; de hele gemeenschap houdt daarmee niet op te bestaan.'),
('p', 'Para um bairro, isso traz perguntas práticas: quem pode consultar as contas, quanto é reservado para reparos e o que acontece se a organização responsável pelo projeto não puder mais continuar seu trabalho?', 'For a neighbourhood, this brings the practical questions back into focus: who can see the accounts, how much is set aside for repairs, and what happens if the organisation behind the project can no longer carry its work?', 'Voor een buurt brengt dat praktische vragen naar voren: wie kan de rekeningen inzien, hoeveel wordt gereserveerd voor reparaties en wat gebeurt er als de organisatie achter het project haar werk niet meer kan voortzetten?'),
('links', [('Relato do Findhorn Foundation Trust', 'Findhorn Foundation Trust’s account', 'Het verhaal van de Findhorn Foundation Trust', 'https://www.findhorn.org/findhorn-foundation-trust')]),
('heading', 'O que isso significa para a IMOBX', 'What this means for IMOBX', 'Wat dit betekent voor IMOBX'),
('p', 'O plano combina o caminho de uma família para ser dona de sua casa com lugares e serviços usados em conjunto pelos vizinhos. Para funcionar, os detalhes precisam ser definidos com as pessoas envolvidas e examinados à luz da lei brasileira.', 'The plan combines a family’s path to owning a house with places and services that neighbours use together. For that to work, the details have to be settled with the people involved and tested against Brazilian law.', 'Het plan combineert de weg van een gezin naar een eigen huis met plekken en voorzieningen die buren samen gebruiken. De details moeten met de betrokkenen worden vastgesteld en aan de Braziliaanse wet worden getoetst.'),
('p', 'As perguntas incluem como a área verde, a cisterna, os equipamentos solares e os caminhos permanecem compartilhados depois que as famílias recebem o título; quem paga pela manutenção; como os moradores decidem e resolvem disputas; e o que acontece quando uma família sai ou uma casa é vendida. Os contratos de moradia das famílias também precisam de proteção contra mudanças impostas por votação.', 'The questions include how the green, cistern, solar equipment and paths stay shared after families receive title; who pays for upkeep; how residents make decisions and resolve disputes; and what happens when a family leaves or a house is sold. Families’ housing agreements also need protection from changes imposed by a vote.', 'De vragen zijn onder meer hoe het groen, het waterreservoir, de zonne-installatie en de paden gedeeld blijven nadat gezinnen hun eigendomstitel ontvangen; wie het onderhoud betaalt; hoe bewoners besluiten nemen en conflicten oplossen; en wat gebeurt als een gezin vertrekt of een huis verkoopt. Ook moeten woonovereenkomsten van gezinnen beschermd worden tegen wijzigingen die via een stemming worden opgelegd.'),
('p', 'As comunidades desta pesquisa oferecem maneiras de pensar sobre essas perguntas. Nenhuma oferece à IMOBX uma estrutura jurídica pronta ou garante que um bairro vá durar.', 'The communities in this research offer ways to think about those questions. None gives IMOBX a ready-made legal structure or guarantees that a neighbourhood will last.', 'De gemeenschappen in dit onderzoek bieden manieren om over die vragen na te denken. Geen ervan geeft IMOBX een kant-en-klare juridische structuur of garandeert dat een buurt blijft bestaan.'),
]

INTRO = [
('heading', 'Quem cuida dos espaços que os vizinhos dividem?', 'Who looks after the places neighbours share?', 'Wie zorgt voor de plekken die buren delen?'),
('p', 'Uma área verde, uma cisterna ou um caminho pode unir vizinhos. Ao longo dos anos, os moradores também precisam decidir quem cuida desses espaços, quem paga pelos reparos e o que acontece quando uma casa é vendida.', 'A green, a cistern or a path can bring neighbours together. Over the years, residents also need to decide who cares for these places, who pays for repairs and what happens when a house is sold.', 'Een groene plek, een waterreservoir of een pad kan buren samenbrengen. Door de jaren heen moeten bewoners ook beslissen wie ervoor zorgt, wie reparaties betaalt en wat er gebeurt als een huis wordt verkocht.'),
('p', 'No Uruguai, famílias de cooperativas se mobilizaram para defender a propriedade coletiva. Na ecovila Earthaven, moradores mudaram seu processo de decisão depois de enfrentar dificuldades com o poder de veto individual. Nossa pesquisa reúne essas e outras experiências para pensar no que deve permanecer compartilhado na IMOBX.', 'In Uruguay, cooperative families organised to defend collective ownership. At Earthaven Ecovillage, residents changed their decision process after struggling with individual vetoes. Our research brings these and other experiences together to consider what should remain shared in IMOBX.', 'In Uruguay kwamen gezinnen uit coöperaties in actie om gezamenlijk eigendom te verdedigen. In ecodorp Earthaven veranderden bewoners hun besluitproces nadat zij moeite hadden met individuele veto’s. Ons onderzoek brengt deze en andere ervaringen samen om na te denken over wat bij IMOBX gedeeld moet blijven.'),
('action', 'Ler a pesquisa sobre os espaços compartilhados', 'Read the research on shared spaces', 'Lees het onderzoek naar gedeelde plekken'),
]

def dutch_strings():
    for item in STORY + INTRO:
        if item[0] == 'links':
            for pt, en, nl, url in item[1]:
                yield en, nl
        else:
            yield item[2], item[3]


def introduction(translated):
    pieces = ['<section id="commons-research">']
    for kind, pt, en, nl in INTRO:
        tag = {'heading': 'h2', 'p': 'p', 'action': 'a'}[kind]
        attrs = 'href="commons-research.html"' if kind == 'action' else ''
        value = translated(pt, en, tag, attrs)
        pieces.append('<p>' + value + '</p>' if kind == 'action' else value)
    return ''.join(pieces) + '</section>'


def article(translated):
    pieces = ['<main class="paper guide-paper band-page" id="main">']
    for item in STORY:
        if item[0] == 'links':
            pieces.append('<p class="idea-source">' + ' · '.join(
                translated(pt, en, 'a', 'href="' + escape(url, quote=True) + '" rel="noopener"')
                for pt, en, nl, url in item[1]) + '</p>')
        else:
            kind, pt, en, nl = item
            pieces.append(translated(pt, en, {'title':'h1', 'heading':'h2', 'p':'p'}[kind]))
    pieces.append('<p>' + translated('Voltar aos recursos', 'Back to resources', 'a', 'href="resources.html#commons-research"') + '</p></main>')
    return ''.join(pieces)
